#include <iostream>
#include <string>
#include <cstdint>

void PutFixed64(std::string* dst, uint64_t value) {
  char buf[8];
  for (int i = 0; i < 8; i++) {
    buf[i] = static_cast<char>(value & 0xff);
    value >>= 8;
  }
  dst->append(buf, 8);
}

int main() {
  // Test from the leveldb test suite
  std::string dst;
  PutFixed64(&dst, 0x0807060504030201ull);

  // Verify the output
  bool pass = true;
  pass &= (static_cast<unsigned char>(dst[0]) == 0x01);
  pass &= (static_cast<unsigned char>(dst[1]) == 0x02);
  pass &= (static_cast<unsigned char>(dst[2]) == 0x03);
  pass &= (static_cast<unsigned char>(dst[3]) == 0x04);
  pass &= (static_cast<unsigned char>(dst[4]) == 0x05);
  pass &= (static_cast<unsigned char>(dst[5]) == 0x06);
  pass &= (static_cast<unsigned char>(dst[6]) == 0x07);
  pass &= (static_cast<unsigned char>(dst[7]) == 0x08);

  std::cout << "Size: " << dst.size() << " (expected 8)" << std::endl;
  std::cout << "Test: " << (pass ? "PASS" : "FAIL") << std::endl;

  // Test with various values
  dst.clear();
  for (int power = 0; power <= 63; power++) {
    uint64_t v = static_cast<uint64_t>(1) << power;
    PutFixed64(&dst, v - 1);
    PutFixed64(&dst, v + 0);
    PutFixed64(&dst, v + 1);
  }

  std::cout << "Total size: " << dst.size() << " (expected " << 3 * 64 << ")" << std::endl;

  return pass ? 0 : 1;
}

