#include <string>
#include <cstdint>

void PutFixed64(std::string* dst, uint64_t value) {
  char buf[8];
  for (int i = 0; i < 8; i++) {
    buf[i] = static_cast<char>(value & 0xff);
    value >>= 8;
  }
  dst->append(buf, 8);
}

int main() {
  std::string dst;
  PutFixed64(&dst, 0x0807060504030201ull);

  bool pass = true;
  pass &= (static_cast<unsigned char>(dst[0]) == 0x01);
  pass &= (static_cast<unsigned char>(dst[1]) == 0x02);
  pass &= (static_cast<unsigned char>(dst[2]) == 0x03);
  pass &= (static_cast<unsigned char>(dst[3]) == 0x04);
  pass &= (static_cast<unsigned char>(dst[4]) == 0x05);
  pass &= (static_cast<unsigned char>(dst[5]) == 0x06);
  pass &= (static_cast<unsigned char>(dst[6]) == 0x07);
  pass &= (static_cast<unsigned char>(dst[7]) == 0x08);

  return pass ? 0 : 1;
}

#include <cstdint>
#include <string>

void PutFixed64(std::string* dst, uint64_t value) {
  char buf[8];
  for (int i = 0; i < 8; i++) {
    buf[i] = static_cast<char>(value & 0xff);
    value >>= 8;
  }
  dst->append(buf, 8);
}

bool test_encoding() {
  std::string dst;
  PutFixed64(&dst, 0x0807060504030201ull);
  if (dst.size() != 8) return false;
  if ((unsigned char)dst[0] != 0x01) return false;
  if ((unsigned char)dst[1] != 0x02) return false;
  if ((unsigned char)dst[2] != 0x03) return false;
  if ((unsigned char)dst[3] != 0x04) return false;
  if ((unsigned char)dst[4] != 0x05) return false;
  if ((unsigned char)dst[5] != 0x06) return false;
  if ((unsigned char)dst[6] != 0x07) return false;
  if ((unsigned char)dst[7] != 0x08) return false;
  return true;
}

int main() {
  return test_encoding() ? 0 : 1;
}

#include <cstdint>
#include <string>

void PutFixed64(std::string* dst, uint64_t value) {
  char buf[8];
  for (int i = 0; i < 8; i++) {
    buf[i] = static_cast<char>(value & 0xff);
    value >>= 8;
  }
  dst->append(buf, 8);
}

int test_main() {
  std::string dst;
  PutFixed64(&dst, 0x0807060504030201ull);
  if (dst.size() != 8) return 1;
  if ((unsigned char)dst[0] != 0x01) return 2;
  if ((unsigned char)dst[1] != 0x02) return 3;
  if ((unsigned char)dst[2] != 0x03) return 4;
  if ((unsigned char)dst[3] != 0x04) return 5;
  if ((unsigned char)dst[4] != 0x05) return 6;
  if ((unsigned char)dst[5] != 0x06) return 7;
  if ((unsigned char)dst[6] != 0x07) return 8;
  if ((unsigned char)dst[7] != 0x08) return 9;
  return 0;
}

